  var feedResponse = http.get({ url: config.services.nasa.imageOfTheDayFeedUrl })
  var feed = rss.parse({ xml: feedResponse.text })
  var news = list.map({
    items: feed.items,
    select: {
      title: current.title,
      description: current.description,
      imageUrl: current.imageUrl,
      link: current.link,
      pubDate: current.pubDate
    }
  })
  result.news = news
  result.count = news.length
  return result
}

