async (page) => {
  const url = "http://127.0.0.1:19080/convertigo/projects/sample_HelloWorldFlowRun9/DisplayObjects/mobile/index.html";
  let navigationError = "";
  try {
    await page.goto(url, { waitUntil: "domcontentloaded", timeout: 20000 });
  } catch (error) {
    navigationError = String(error);
  }
  return {
    url: page.url(),
    title: await page.title().catch(() => ""),
    navigationError,
    bodyText: (await page.locator("body").innerText({ timeout: 5000 }).catch(() => "")).slice(0, 1200)
  };
}
